from http import HTTPStatus
from typing import TYPE_CHECKING
from unittest.mock import patch

import pytest
import requests

from rotkehlchen.chain.evm.types import EvmIndexer
from rotkehlchen.db.settings import CachedSettings
from rotkehlchen.tests.utils.api import (
    api_url_for,
    assert_error_response,
    assert_proper_response_with_result,
)
from rotkehlchen.types import ChainID

if TYPE_CHECKING:
    from rotkehlchen.api.server import APIServer


@pytest.mark.parametrize('ethereum_accounts', [[]])
def test_query_transactions_errors(rotkehlchen_api_server: APIServer) -> None:
    """Check various validation errors when querying blockchain transactions."""
    for json_data, error_msg in (
        (  # Untracked/malformed address with no chain specified
            {'accounts': [{'address': '0xasdasd'}]},
            'The address 0xasdasd is not tracked on any chain in rotki',
        ), (  # Untracked address with the chain specified
            {'accounts': [{'address': '0xaFB7ed3beBE50E0b62Fa862FAba93e7A46e59cA7', 'blockchain': 'eth'}]},  # noqa: E501
            'The address 0xaFB7ed3beBE50E0b62Fa862FAba93e7A46e59cA7 on ethereum is not tracked in rotki',  # noqa: E501
        ), (  # Malformed address with the chain specified
            {'accounts': [{'address': '0xasdasd', 'blockchain': 'optimism'}]},
            'The address 0xasdasd is not a valid optimism address.',
        ), (  # Blockchain that we don't support transactions for yet
            {'accounts': [{'address': '0xaFB7ed3beBE50E0b62Fa862FAba93e7A46e59cA7', 'blockchain': 'avax'}]},  # noqa: E501
            'rotki does not support transactions for avalanche',
        ), (  # Malformed from_timestamp
            {'accounts': [{'address': '0xaFB7ed3beBE50E0b62Fa862FAba93e7A46e59cA7'}], 'from_timestamp': 'foo'},  # noqa: E501
            'Failed to deserialize a timestamp entry from string foo',
        ), (  # Malformed to_timestamp
            {'accounts': [{'address': '0xaFB7ed3beBE50E0b62Fa862FAba93e7A46e59cA7'}], 'to_timestamp': 'foo'},  # noqa: E501
            'Failed to deserialize a timestamp entry from string foo',
        ),
    ):
        response = requests.post(
            api_url_for(
                rotkehlchen_api_server,
                'blockchaintransactionsresource',
            ), json=json_data,
        )
        assert_error_response(
            response=response,
            contained_in_msg=error_msg,
            status_code=HTTPStatus.BAD_REQUEST,
        )


@pytest.mark.parametrize('have_decoders', [[True]])
@pytest.mark.parametrize('start_with_valid_premium', [True])
@pytest.mark.parametrize('ethereum_accounts', [['0xc37b40ABdB939635068d3c5f13E7faF686F03B65']])
@pytest.mark.vcr(filter_query_parameters=['apikey'])
def test_decode_given_transactions_custom_indexer(rotkehlchen_api_server: APIServer) -> None:
    """Ensure a custom indexer is used first when redecode endpoint is called with one.
    In this test we check that the validation passes correctly the order and they are reset after
    executing the logic.
    """
    custom_indexer = EvmIndexer.ROUTESCAN
    default_order = CachedSettings().get_evm_indexers_order_for_chain(ChainID.ETHEREUM)
    assert default_order[0] != custom_indexer
    node_inquirer = rotkehlchen_api_server.rest_api.rotkehlchen.chains_aggregator.ethereum.node_inquirer  # noqa: E501
    call_order: list[EvmIndexer] = []
    available_indexers = node_inquirer.available_indexers
    original_try_indexers = node_inquirer._try_indexers

    def tracking_try_indexers(func):
        def wrapped(indexer_api):
            for name, candidate in available_indexers.items():
                if candidate is indexer_api:
                    call_order.append(name)
                    break
            return func(indexer_api)

        return original_try_indexers(wrapped)

    with patch.object(node_inquirer, '_try_indexers', side_effect=tracking_try_indexers):
        result = requests.put(
            api_url_for(
                rotkehlchen_api_server,
                'transactionsdecodingresource',
            ), json={
                'async_query': False,
                'chain': 'eth',
                'tx_refs': ['0xc23d562c935fc3afd31a3597d647dee302421659ad9fc5ca77e2b257df400532'],
                'delete_custom': False,
                'custom_indexers_order': [custom_indexer.serialize()],
            },
        )
    outcome = assert_proper_response_with_result(
        response=result,
        rotkehlchen_api_server=rotkehlchen_api_server,
        async_query=False,
    )
    assert outcome is True
    assert CachedSettings().get_evm_indexers_order_for_chain(ChainID.ETHEREUM) == default_order
    assert all(indexer == custom_indexer for indexer in call_order)

    result = requests.put(  # test validation of indexers
        api_url_for(
            rotkehlchen_api_server,
            'transactionsdecodingresource',
        ), json={
            'async_query': False,
            'chain': 'eth',
            'tx_refs': ['0xc23d562c935fc3afd31a3597d647dee302421659ad9fc5ca77e2b257df400532'],
            'delete_custom': False,
            'custom_indexers_order': ['fakeIndexer'],
        },
    )
    assert_error_response(response=result, contained_in_msg='Invalid EVM indexer: fakeIndexer')

import type { CreateAccountPayload, LoginCredentials } from '@/modules/auth/login';
import { server } from '@test/setup-files/server';
import { type DefaultBodyType, http, HttpResponse } from 'msw';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { useUsersApi } from './use-users-api';

const backendUrl = process.env.VITE_BACKEND_URL;
const colibriUrl = `${backendUrl}/colibri`;

describe('composables/api/session/users', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('getUserProfiles', () => {
    it('should return list of user profile names', async () => {
      server.use(
        http.get(`${backendUrl}/api/1/users`, () =>
          HttpResponse.json({
            result: {
              user1: 'loggedin',
              user2: 'loggedout',
              user3: 'loggedout',
            },
            message: '',
          })),
      );

      const { getUserProfiles } = useUsersApi();
      const result = await getUserProfiles();

      expect(result).toEqual(['user1', 'user2', 'user3']);
    });
  });

  describe('checkIfLogged', () => {
    it('should return true when user is logged in', async () => {
      server.use(
        http.get(`${backendUrl}/api/1/users`, () =>
          HttpResponse.json({
            result: {
              testuser: 'loggedin',
              otheruser: 'loggedout',
            },
            message: '',
          })),
      );

      const { checkIfLogged } = useUsersApi();
      const result = await checkIfLogged('testuser');

      expect(result).toBe(true);
    });

    it('should return false when user is logged out', async () => {
      server.use(
        http.get(`${backendUrl}/api/1/users`, () =>
          HttpResponse.json({
            result: {
              testuser: 'loggedout',
            },
            message: '',
          })),
      );

      const { checkIfLogged } = useUsersApi();
      const result = await checkIfLogged('testuser');

      expect(result).toBe(false);
    });
  });

  describe('loggedUsers', () => {
    it('should return only logged in users', async () => {
      server.use(
        http.get(`${backendUrl}/api/1/users`, () =>
          HttpResponse.json({
            result: {
              user1: 'loggedin',
              user2: 'loggedout',
              user3: 'loggedin',
              user4: 'loggedout',
            },
            message: '',
          })),
      );

      const { loggedUsers } = useUsersApi();
      const result = await loggedUsers();

      expect(result).toEqual(['user1', 'user3']);
    });

    it('should return empty array when no users are logged in', async () => {
      server.use(
        http.get(`${backendUrl}/api/1/users`, () =>
          HttpResponse.json({
            result: {
              user1: 'loggedout',
              user2: 'loggedout',
            },
            message: '',
          })),
      );

      const { loggedUsers } = useUsersApi();
      const result = await loggedUsers();

      expect(result).toEqual([]);
    });
  });

  describe('createAccount', () => {
    it('should send PUT request with snake_case payload for basic account creation', async () => {
      let capturedBody: DefaultBodyType = null;

      server.use(
        http.put(`${backendUrl}/api/1/users`, async ({ request }) => {
          capturedBody = await request.json();
          return HttpResponse.json({
            result: {
              task_id: 123,
            },
            message: '',
          });
        }),
      );

      const { createAccount } = useUsersApi();
      const payload: CreateAccountPayload = {
        credentials: {
          username: 'newuser',
          password: 'securepassword123',
        },
        initialSettings: {
          submitUsageAnalytics: true,
        },
      };

      const result = await createAccount(payload);

      expect(result.taskId).toBe(123);
      expect(capturedBody).toEqual({
        async_query: true,
        initial_settings: {
          submit_usage_analytics: true,
        },
        name: 'newuser',
        password: 'securepassword123',
      });
    });

    it('should send PUT request with premium setup when provided', async () => {
      let capturedBody: DefaultBodyType = null;

      server.use(
        http.put(`${backendUrl}/api/1/users`, async ({ request }) => {
          capturedBody = await request.json();
          return HttpResponse.json({
            result: {
              task_id: 456,
            },
            message: '',
          });
        }),
      );

      const { createAccount } = useUsersApi();
      const payload: CreateAccountPayload = {
        credentials: {
          username: 'premiumuser',
          password: 'password123',
        },
        initialSettings: {
          submitUsageAnalytics: false,
        },
        premiumSetup: {
          apiKey: 'premium-api-key',
          apiSecret: 'premium-api-secret',
          syncDatabase: true,
        },
      };

      const result = await createAccount(payload);

      expect(result.taskId).toBe(456);
      expect(capturedBody).toEqual({
        async_query: true,
        initial_settings: {
          submit_usage_analytics: false,
        },
        name: 'premiumuser',
        password: 'password123',
        premium_api_key: 'premium-api-key',
        premium_api_secret: 'premium-api-secret',
        sync_database: true,
      });
    });
  });

  describe('login', () => {
    it('should send POST request with snake_case credentials', async () => {
      let capturedBody: DefaultBodyType = null;
      let capturedUrl = '';

      server.use(
        http.post(`${backendUrl}/api/1/users/:username`, async ({ request }) => {
          capturedUrl = request.url;
          capturedBody = await request.json();
          return HttpResponse.json({
            result: {
              task_id: 789,
            },
            message: '',
          });
        }),
      );

      const { login } = useUsersApi();
      const credentials: LoginCredentials = {
        username: 'testuser',
        password: 'mypassword',
        syncApproval: 'yes',
        resumeFromBackup: false,
      };

      const result = await login(credentials);

      expect(result.taskId).toBe(789);
      expect(capturedUrl).toContain('/users/testuser');
      expect(capturedBody).toEqual({
        password: 'mypassword',
        sync_approval: 'yes',
        resume_from_backup: false,
        async_query: true,
      });
    });

    it('should send POST request with minimal credentials', async () => {
      let capturedBody: DefaultBodyType = null;

      server.use(
        http.post(`${backendUrl}/api/1/users/:username`, async ({ request }) => {
          capturedBody = await request.json();
          return HttpResponse.json({
            result: {
              task_id: 101,
            },
            message: '',
          });
        }),
      );

      const { login } = useUsersApi();
      const credentials: LoginCredentials = {
        username: 'minimaluser',
        password: 'pass',
      };

      const result = await login(credentials);

      expect(result.taskId).toBe(101);
      expect(capturedBody).toEqual({
        password: 'pass',
        async_query: true,
      });
    });
  });

  describe('colibriLogin', () => {
    it('should send POST request to colibri API with snake_case payload', async () => {
      let capturedBody: DefaultBodyType = null;

      // Note: colibri endpoints use baseURL override, so no /api/1 prefix
      server.use(
        http.post(`${colibriUrl}/user`, async ({ request }) => {
          capturedBody = await request.json();
          return HttpResponse.json({
            result: true,
            message: '',
          });
        }),
      );

      const { colibriLogin } = useUsersApi();
      const result = await colibriLogin({
        username: 'colibriuser',
        password: 'colibripass',
      });

      expect(result).toBe(true);
      expect(capturedBody).toEqual({
        username: 'colibriuser',
        password: 'colibripass',
      });
    });

    it('should relock and retry when colibri still holds a db', async () => {
      const calls: string[] = [];
      let unlockAttempts = 0;

      // colibri refuses to unlock while it holds any client, and cannot say whose it is.
      server.use(
        http.post(`${colibriUrl}/user`, () => {
          calls.push('unlock');
          unlockAttempts += 1;
          if (unlockAttempts === 1) {
            return HttpResponse.json({
              result: null,
              message: 'The DB is already unlocked',
            }, { status: 400 });
          }
          return HttpResponse.json({ result: true, message: '' });
        }),
        http.post(`${colibriUrl}/user/logout`, () => {
          calls.push('lock');
          return HttpResponse.json({ result: true, message: '' });
        }),
      );

      const { colibriLogin } = useUsersApi();
      const result = await colibriLogin({ username: 'bob', password: 'pw' });

      expect(result).toBe(true);
      expect(calls).toEqual(['unlock', 'lock', 'unlock']);
    });

    it('should reject when the retried unlock also fails', async () => {
      let unlockAttempts = 0;

      server.use(
        http.post(`${colibriUrl}/user`, () => {
          unlockAttempts += 1;
          return HttpResponse.json({
            result: null,
            message: 'The DB is already unlocked',
          }, { status: 400 });
        }),
        http.post(`${colibriUrl}/user/logout`, () =>
          HttpResponse.json({ result: true, message: '' })),
      );

      const { colibriLogin } = useUsersApi();

      await expect(colibriLogin({ username: 'bob', password: 'pw' }))
        .rejects
        .toThrow('The DB is already unlocked');
      // retried exactly once, never looped
      expect(unlockAttempts).toBe(2);
    });

    it('should not relock when the unlock fails for another reason', async () => {
      let lockCalled = false;

      server.use(
        http.post(`${colibriUrl}/user`, () =>
          HttpResponse.json({
            result: null,
            message: 'Failed to open database at /data/users/bob/rotkehlchen.db',
          }, { status: 400 })),
        http.post(`${colibriUrl}/user/logout`, () => {
          lockCalled = true;
          return HttpResponse.json({ result: true, message: '' });
        }),
      );

      const { colibriLogin } = useUsersApi();

      await expect(colibriLogin({ username: 'bob', password: 'pw' }))
        .rejects
        .toThrow('Failed to open database');
      expect(lockCalled).toBe(false);
    });
  });

  describe('logout', () => {
    it('should send PATCH request with logout action', async () => {
      let capturedBody: DefaultBodyType = null;
      let capturedUrl = '';

      // Note: colibri logout uses baseURL override, so no /api/1 prefix
      server.use(
        http.post(`${colibriUrl}/user/logout`, () =>
          HttpResponse.json({
            result: true,
            message: '',
          })),
        http.patch(`${backendUrl}/api/1/users/:username`, async ({ request }) => {
          capturedUrl = request.url;
          capturedBody = await request.json();
          return HttpResponse.json({
            result: true,
            message: '',
          });
        }),
      );

      const { logout } = useUsersApi();
      const result = await logout('testuser');

      expect(result).toBe(true);
      expect(capturedUrl).toContain('/users/testuser');
      expect(capturedBody).toEqual({
        action: 'logout',
      });
    });

    it('should lock colibri before logging out of core', async () => {
      const calls: string[] = [];

      server.use(
        http.post(`${colibriUrl}/user/logout`, () => {
          calls.push('colibri');
          return HttpResponse.json({ result: true, message: '' });
        }),
        http.patch(`${backendUrl}/api/1/users/:username`, () => {
          calls.push('core');
          return HttpResponse.json({ result: true, message: '' });
        }),
      );

      const { logout } = useUsersApi();
      await logout('testuser');

      expect(calls).toEqual(['colibri', 'core']);
    });

    it('should still log out of core when colibri is already locked', async () => {
      let coreCalled = false;

      server.use(
        http.post(`${colibriUrl}/user/logout`, () =>
          HttpResponse.json({
            result: null,
            message: 'DB not unlocked',
          }, { status: 400 })),
        http.patch(`${backendUrl}/api/1/users/:username`, () => {
          coreCalled = true;
          return HttpResponse.json({ result: true, message: '' });
        }),
      );

      const { logout } = useUsersApi();
      const result = await logout('testuser');

      expect(result).toBe(true);
      expect(coreCalled).toBe(true);
    });

    it('should not log out of core when colibri fails for another reason', async () => {
      let coreCalled = false;

      server.use(
        http.post(`${colibriUrl}/user/logout`, () =>
          HttpResponse.json({
            result: null,
            message: 'Database error while closing the connection',
          }, { status: 400 })),
        http.patch(`${backendUrl}/api/1/users/:username`, () => {
          coreCalled = true;
          return HttpResponse.json({ result: true, message: '' });
        }),
      );

      const { logout } = useUsersApi();

      await expect(logout('testuser')).rejects.toThrow('Database error while closing the connection');
      expect(coreCalled).toBe(false);
    });

    it('should return true when colibri logout, whose baseURL override drops the /api/1 prefix, returns 409 conflict', async () => {
      server.use(
        http.post(`${colibriUrl}/user/logout`, () =>
          HttpResponse.json({
            result: true,
            message: '',
          })),
        http.patch(`${backendUrl}/api/1/users/:username`, () =>
          HttpResponse.json({
            result: false,
            message: 'Already logged out',
          }, { status: 409 })),
      );

      const { logout } = useUsersApi();
      const result = await logout('testuser');

      expect(result).toBe(true);
    });
  });

  describe('changeUserPassword', () => {
    it('should send PATCH request with password change payload', async () => {
      let capturedBody: DefaultBodyType = null;
      let capturedUrl = '';

      server.use(
        http.patch(`${backendUrl}/api/1/users/:username/password`, async ({ request }) => {
          capturedUrl = request.url;
          capturedBody = await request.json();
          return HttpResponse.json({
            result: true,
            message: '',
          });
        }),
      );

      const { changeUserPassword } = useUsersApi();
      const result = await changeUserPassword('testuser', 'oldpassword', 'newpassword');

      expect(result).toBe(true);
      expect(capturedUrl).toContain('/users/testuser/password');
      expect(capturedBody).toEqual({
        current_password: 'oldpassword',
        name: 'testuser',
        new_password: 'newpassword',
      });
    });

    it('should throw error on authentication failure', async () => {
      server.use(
        http.patch(`${backendUrl}/api/1/users/:username/password`, () =>
          HttpResponse.json({
            result: null,
            message: 'Invalid current password',
          })),
      );

      const { changeUserPassword } = useUsersApi();

      await expect(changeUserPassword('testuser', 'wrongpassword', 'newpassword'))
        .rejects
        .toThrow('Invalid current password');
    });
  });

  describe('authenticate', () => {
    it('should post the password to the authenticate endpoint', async () => {
      let captured: DefaultBodyType;
      server.use(
        http.post(`${backendUrl}/api/1/users/alice/authenticate`, async ({ request }) => {
          captured = await request.json();
          return HttpResponse.json({ result: {}, message: '' });
        }),
      );

      const { authenticate } = useUsersApi();
      await expect(authenticate({ password: 's3cret', username: 'alice' })).resolves.toBeUndefined();
      expect(captured).toEqual({ password: 's3cret' });
    });

    it('should reject on a wrong-password 401', async () => {
      server.use(
        http.post(`${backendUrl}/api/1/users/alice/authenticate`, () =>
          HttpResponse.json(
            { result: null, message: 'Wrong username/password combination' },
            { status: 401 },
          )),
      );

      const { authenticate } = useUsersApi();
      await expect(authenticate({ password: 'wrong', username: 'alice' })).rejects.toThrow();
    });
  });
});

import { server } from '@test/setup-files/server';
import { type DefaultBodyType, http, HttpResponse } from 'msw';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { usePremiumCredentialsApi } from './use-premium-credentials-api';

const backendUrl = process.env.VITE_BACKEND_URL;

describe('composables/api/session/premium-credentials', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('setPremiumCredentials', () => {
    it('should set premium credentials', async () => {
      let capturedBody: DefaultBodyType = null;
      let capturedUsername: string | null = null;

      server.use(
        http.patch(`${backendUrl}/api/1/users/:username`, async ({ request, params }) => {
          capturedBody = await request.json();
          capturedUsername = String(params.username);
          return HttpResponse.json({
            result: true,
            message: '',
          });
        }),
      );

      const { setPremiumCredentials } = usePremiumCredentialsApi();
      const result = await setPremiumCredentials('testuser', 'api-key-123', 'api-secret-456');

      expect(capturedUsername).toBe('testuser');
      expect(capturedBody).toEqual({
        premium_api_key: 'api-key-123',
        premium_api_secret: 'api-secret-456',
      });
      expect(result).toBe(true);
    });

    it('should throw error on invalid credentials', async () => {
      server.use(
        http.patch(`${backendUrl}/api/1/users/:username`, () =>
          HttpResponse.json({
            result: null,
            message: 'Invalid API credentials',
          })),
      );

      const { setPremiumCredentials } = usePremiumCredentialsApi();

      await expect(setPremiumCredentials('testuser', 'bad-key', 'bad-secret'))
        .rejects
        .toThrow('Invalid API credentials');
    });
  });

  describe('deletePremiumCredentials', () => {
    it('should delete premium credentials', async () => {
      server.use(
        http.delete(`${backendUrl}/api/1/premium`, () =>
          HttpResponse.json({
            result: true,
            message: '',
          })),
      );

      const { deletePremiumCredentials } = usePremiumCredentialsApi();
      const result = await deletePremiumCredentials();

      expect(result).toBe(true);
    });

    it('should throw error on failure', async () => {
      server.use(
        http.delete(`${backendUrl}/api/1/premium`, () =>
          HttpResponse.json({
            result: null,
            message: 'No premium credentials to delete',
          })),
      );

      const { deletePremiumCredentials } = usePremiumCredentialsApi();

      await expect(deletePremiumCredentials())
        .rejects
        .toThrow('No premium credentials to delete');
    });
  });

  describe('getPremiumCapabilities', () => {
    it('should get premium capabilities', async () => {
      server.use(
        http.get(`${backendUrl}/api/1/premium/capabilities`, () =>
          HttpResponse.json({
            result: {
              ethStakingView: { enabled: true, minimumTier: 'Lite' },
              eventAnalysisView: { enabled: true, minimumTier: 'Basic' },
              graphsView: { enabled: false, minimumTier: 'Advanced' },
            },
            message: '',
          })),
      );

      const { getPremiumCapabilities } = usePremiumCredentialsApi();
      const result = await getPremiumCapabilities();

      expect(result.ethStakingView?.enabled).toBe(true);
      expect(result.ethStakingView?.minimumTier).toBe('Lite');
      expect(result.eventAnalysisView?.enabled).toBe(true);
      expect(result.graphsView?.enabled).toBe(false);
    });

    it('should return defaults when no premium', async () => {
      server.use(
        http.get(`${backendUrl}/api/1/premium/capabilities`, () =>
          HttpResponse.json({
            result: {},
            message: '',
          })),
      );

      const { getPremiumCapabilities } = usePremiumCredentialsApi();
      const result = await getPremiumCapabilities();

      expect(result.ethStakingView?.enabled).toBeUndefined();
      expect(result.eventAnalysisView?.enabled).toBeUndefined();
      expect(result.graphsView?.enabled).toBeUndefined();
    });

    it('drops invalid keys and keeps valid ones', async () => {
      server.use(
        http.get(`${backendUrl}/api/1/premium/capabilities`, () =>
