  });

  describe('info', () => {
    it('should send GET request and returns database info', async () => {
      server.use(
        http.get(`${backendUrl}/api/1/database/info`, () =>
          HttpResponse.json({
            result: {
              globaldb: {
                globaldb_assets_version: 15,
                globaldb_schema_version: 8,
              },
              userdb: {
                info: {
                  filepath: '/data/user.db',
                  size: 1048576,
                  version: 42,
                },
                backups: [
                  {
                    size: 524288,
                    time: 1700000000,
                    version: 41,
                  },
                ],
              },
            },
            message: '',
          })),
      );

      const api = useBackupApi();
